package com.crm.customer.service;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import javax.xml.stream.*;import org.springframework.stereotype.Service;import com.crm.customer.dto.*;import java.util.function.Function;
/** Bounded OOXML values-only reader. No spreadsheet engine or formula evaluation. */
@Service public class CustomerXlsxService {private static final int MAX_ZIP=5*1024*1024,MAX_EXPANDED=10*1024*1024,MAX_ROWS=2001,MAX_TEXT=5000;private final CustomerCsvService csv;public CustomerXlsxService(CustomerCsvService c){csv=c;}
 public CustomerCsvService.ImportReport read(byte[] bytes,Function<CustomerRequest,CustomerResponse> creator){return csv.importCsv(toCsv(bytes),creator);}
 public byte[] toCsv(byte[] bytes){if(bytes==null||bytes.length==0||bytes.length>MAX_ZIP)throw invalid();Map<String,byte[]> parts=new HashMap<>();int total=0,count=0;try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;byte[] block=new byte[4096];while((e=zip.getNextEntry())!=null){String name=e.getName();if(++count>100||name.contains("..")||name.startsWith("/")||name.indexOf('\\')>=0||parts.containsKey(name))throw invalid();String lower=name.toLowerCase(Locale.ROOT);if(lower.contains("vbaproject")||lower.contains("macrosheet")||lower.contains("externallink")||lower.contains("embeddings")||!e.isDirectory()&&!lower.endsWith(".xml")&&!lower.endsWith(".rels"))throw invalid();ByteArrayOutputStream out=new ByteArrayOutputStream();int n;while((n=zip.read(block))!=-1){total+=n;if(total>MAX_EXPANDED)throw invalid();out.write(block,0,n);}if(!e.isDirectory())parts.put(name,out.toByteArray());}}catch(IOException ex){throw invalid();}
 if(!parts.containsKey("[Content_Types].xml")||!parts.containsKey("xl/workbook.xml"))throw invalid();List<String> sheets=parts.keySet().stream().filter(n->n.matches("xl/worksheets/[^/]+\\.xml")).toList();if(sheets.size()!=1)throw new IllegalArgumentException("XLSX requires exactly one worksheet");
 for(var part:parts.entrySet()){if(part.getKey().endsWith(".rels")||part.getKey().equals("[Content_Types].xml")||part.getKey().equals("xl/workbook.xml"))checkMetadata(part.getValue());}
 List<String> strings=parts.containsKey("xl/sharedStrings.xml")?shared(parts.get("xl/sharedStrings.xml")):List.of();List<List<String>> rows=sheet(parts.get(sheets.getFirst()),strings);if(rows.isEmpty())throw invalid();int width=rows.getFirst().size();if(width<1||width>9)throw invalid();StringBuilder text=new StringBuilder();for(var row:rows){for(int i=0;i<Math.max(width,row.size());i++){if(i>0)text.append(',');text.append('"').append(i<row.size()?row.get(i).replace("\"","\"\""):"").append('"');}text.append('\n');}return text.toString().getBytes(StandardCharsets.UTF_8);}
 private XMLStreamReader xml(byte[] data){try{XMLInputFactory f=XMLInputFactory.newFactory();f.setProperty(XMLInputFactory.SUPPORT_DTD,false);f.setProperty("javax.xml.stream.isSupportingExternalEntities",false);f.setXMLResolver((a,b,c,d)->{throw new XMLStreamException("External XML forbidden");});return f.createXMLStreamReader(new ByteArrayInputStream(data));}catch(XMLStreamException e){throw invalid();}}
 private void forbidden(XMLStreamReader r)throws XMLStreamException{if(r.getEventType()==XMLStreamConstants.DTD||r.getEventType()==XMLStreamConstants.ENTITY_REFERENCE)throw invalid();}
 private void checkMetadata(byte[] data){var r=xml(data);try{int sheets=0;while(r.hasNext()){r.next();forbidden(r);if(r.isStartElement()){if(r.getLocalName().equals("sheet")&&++sheets>1)throw invalid();for(int i=0;i<r.getAttributeCount();i++){String value=r.getAttributeValue(i);if(value.equalsIgnoreCase("External")||value.toLowerCase(Locale.ROOT).contains("macroenabled"))throw invalid();}}}}catch(XMLStreamException e){throw invalid();}finally{close(r);}}
 private List<String> shared(byte[] data){var r=xml(data);List<String> values=new ArrayList<>();StringBuilder value=null;try{while(r.hasNext()){r.next();forbidden(r);if(r.isStartElement()&&r.getLocalName().equals("si"))value=new StringBuilder();else if(r.isStartElement()&&r.getLocalName().equals("t")&&value!=null){value.append(r.getElementText());if(value.length()>MAX_TEXT)throw invalid();}else if(r.isEndElement()&&r.getLocalName().equals("si")){if(value==null||values.size()>=20000)throw invalid();values.add(value.toString());value=null;}}}catch(XMLStreamException e){throw invalid();}finally{close(r);}return values;}
 private List<List<String>> sheet(byte[] data,List<String> strings){var r=xml(data);List<List<String>> rows=new ArrayList<>();List<String> row=null;Set<Integer> cells=new HashSet<>();int number=0,column=-1;String type=null;StringBuilder value=null;try{while(r.hasNext()){r.next();forbidden(r);if(r.isStartElement()){String tag=r.getLocalName();if(tag.equals("f")||tag.equals("formula"))throw new IllegalArgumentException("XLSX formulas are not accepted");if(tag.equals("row")){String n=r.getAttributeValue(null,"r");number=n==null?rows.size()+1:Integer.parseInt(n);if(number<=rows.size()||number>MAX_ROWS)throw invalid();while(rows.size()<number-1)rows.add(new ArrayList<>());row=new ArrayList<>();cells.clear();}else if(tag.equals("c")){if(row==null)throw invalid();String ref=r.getAttributeValue(null,"r");if(ref==null||!ref.matches("[A-I][1-9][0-9]{0,3}")||Integer.parseInt(ref.substring(1))!=number)throw invalid();column=ref.charAt(0)-'A';if(!cells.add(column))throw invalid();type=r.getAttributeValue(null,"t");if(type!=null&&!Set.of("s","inlineStr","str","n").contains(type))throw invalid();value=new StringBuilder();}else if((tag.equals("t")||tag.equals("v"))&&value!=null){value.append(r.getElementText());if(value.length()>MAX_TEXT)throw invalid();}}else if(r.isEndElement()){String tag=r.getLocalName();if(tag.equals("c")){if(value==null||row==null)throw invalid();String v=value.toString();if("s".equals(type)){int index=Integer.parseInt(v);if(index<0||index>=strings.size())throw invalid();v=strings.get(index);}while(row.size()<=column)row.add("");row.set(column,v);value=null;}else if(tag.equals("row")){if(row==null)throw invalid();rows.add(row);row=null;}}}}catch(XMLStreamException|NumberFormatException e){throw invalid();}finally{close(r);}return rows;}
 private void close(XMLStreamReader r){try{r.close();}catch(XMLStreamException ignored){}}private IllegalArgumentException invalid(){return new IllegalArgumentException("Invalid or oversized XLSX: one values-only sheet, 2000 data rows, 9 columns, 5 MiB compressed and 10 MiB expanded maximum");}
}
